@layer components {
  /* Scrollbar styles */
  ::-webkit-scrollbar {
    @apply w-2 h-2;
  }

  ::-webkit-scrollbar-track {
    @apply bg-transparent;
  }

  ::-webkit-scrollbar-thumb {
    @apply bg-gray-300 rounded;
  }

  ::-webkit-scrollbar-thumb:hover {
    @apply bg-gray-400;
  }

  /* Code block wrapper styles */
  .code-block-wrapper {
    @apply my-4;
  }

  /* Remove default pre/code background when using SyntaxHighlighter */
  .markdown-content pre {
    @apply m-0;
    background: transparent !important;
  }
}

@layer utilities {
  .animate-fade-in {
    animation: fadeIn 0.2s ease-out;
  }

  @keyframes fadeIn {
    from {
      opacity: 0;
      transform: translateY(8px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  .animate-pulse-slow {
    animation: pulse-slow 2s ease-in-out infinite;
  }

  @keyframes pulse-slow {
    0%,
    100% {
      opacity: 1;
    }
    50% {
      opacity: 0.5;
    }
  }

  /* Streaming cursor blink */
  .animate-cursor-blink {
    animation: cursorBlink 0.8s step-end infinite;
  }

  @keyframes cursorBlink {
    0%,
    50% {
      opacity: 1;
    }
    51%,
    100% {
      opacity: 0;
    }
  }

  /* Shimmer loading effect */
  .animate-shimmer {
    animation: shimmer 1.5s ease-in-out infinite;
    background: linear-gradient(
      90deg,
      oklch(0.97 0 0) 0%,
      oklch(0.99 0 0) 50%,
      oklch(0.97 0 0) 100%
    );
    background-size: 200% 100%;
  }

  @keyframes shimmer {
    0% {
      background-position: 200% 0;
    }
    100% {
      background-position: -200% 0;
    }
  }

  /* Smooth streaming text - optimized for performance */
  .streaming-content {
    contain: content;
    will-change: contents;
    /* Text naturally accumulates without animation - modern approach */
    /* Only apply subtle fade to newly added content via React */
    animation: none;
  }

  /* Subtle fade-in for streaming content updates */
  .animate-fade-in-subtle {
    animation: fadeInSubtle 0.3s ease-out;
  }

  @keyframes fadeInSubtle {
    from {
      opacity: 0.7;
    }
    to {
      opacity: 1;
    }
  }

  .streaming-markdown {
    contain: content;
  }

  .streaming-cursor {
    display: inline-block;
    width: 2px;
    height: 1em;
    background-color: currentColor;
    margin-left: 2px;
    vertical-align: text-bottom;
    animation: cursorBlink 0.8s step-end infinite;
  }

  /* Coral-colored streaming cursor */
  .streaming-cursor-coral {
    display: inline-block;
    width: 2px;
    height: 1em;
    background-color: #ff6b6b;
    margin-left: 2px;
    vertical-align: text-bottom;
    animation: cursorBlink 0.8s step-end infinite;
  }

  /* ===== Flowtoken-style Character Animation ===== */

  /* Flowtoken animation keyframes */
  @keyframes ft-fadeIn {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }

  @keyframes ft-slideUp {
    from {
      opacity: 0;
      transform: translateY(10px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @keyframes ft-blurIn {
    0% {
      opacity: 0;
      filter: blur(10px);
    }
    100% {
      opacity: 1;
      filter: blur(0);
    }
  }

  @keyframes ft-dropIn {
    0% {
      opacity: 0;
      transform: translateY(-15px);
    }
    100% {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @keyframes ft-wave {
    0% {
      opacity: 0;
      transform: translateY(5px);
    }
    50% {
      opacity: 1;
      transform: translateY(-2px);
    }
    100% {
      transform: translateY(0);
    }
  }

  @keyframes ft-highlight {
    0% {
      background-color: rgba(255, 200, 100, 0.5);
    }
    100% {
      background-color: transparent;
    }
  }

  /* Container for animated markdown during streaming */
  .streaming-markdown {
    contain: content;
    will-change: contents;
  }

  /* Each animated character gets this class */
  .char-animated,
  .char-sp,
  .ft-char,
  .fc {
    display: inline;
    animation: charFadeInUp 0.8s ease-in-out both;
  }

  /* Fade in up animation - inspired by Flowtoken */
  @keyframes charFadeInUp {
    from {
      opacity: 0;
      transform: translateY(4px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  /* Alternative animations (Flowtoken provides these) */

  /* Blur in effect */
  .char-animated-blur {
    animation: charBlurIn 0.8s ease-in-out both;
  }

  @keyframes charBlurIn {
    from {
      opacity: 0;
      filter: blur(8px);
    }
    to {
      opacity: 1;
      filter: blur(0);
    }
  }

  /* Drop in effect */
  .char-animated-drop {
    animation: charDropIn 0.8s ease-in-out both;
  }

  @keyframes charDropIn {
    from {
      opacity: 0;
      transform: translateY(-12px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  /* Wave effect */
  .char-animated-wave {
    animation: charWave 0.8s ease-in-out both;
  }

  @keyframes charWave {
    0%,
    100% {
      transform: translateY(0);
    }
    25% {
      transform: translateY(-3px);
    }
    50% {
      transform: translateY(0);
    }
    75% {
      transform: translateY(3px);
    }
  }

  /* Highlight effect */
  .char-animated-highlight {
    animation: charHighlight 0.8s ease-in-out both;
  }

  @keyframes charHighlight {
    from {
      background-color: rgba(255, 107, 107, 0.3);
    }
    to {
      background-color: transparent;
    }
  }

  /* For completed messages - fade in the whole block */
  .animate-fade-in-up {
    animation: smoothFadeInUp 0.8s ease-in-out;
  }

  @keyframes smoothFadeInUp {
    from {
      opacity: 0;
      transform: translateY(8px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  /* Spinner rotation */
  .animate-spin-slow {
    animation: spin 1.5s linear infinite;
  }

  @keyframes spin {
    from {
      transform: rotate(0deg);
    }
    to {
      transform: rotate(360deg);
    }
  }
}

import { app, BrowserWindow, ipcMain } from 'electron';
import path from 'path';
import { spawn, ChildProcess } from 'child_process';
import fs from 'fs';

// Store the backend server process
let backendProcess: ChildProcess | null = null;
let isQuitting = false;

// Safe console.log that handles EPIPE
function safeLog(prefix: string, message: string): void {
  if (isQuitting) return;
  try {
    // Use process.stdout.write directly with error handling
    process.stdout.write(`${prefix} ${message}\n`, (err) => {
      // Ignore EPIPE and other write errors
      if (err && err.message?.includes('EPIPE')) {
        // Mark as quitting to prevent further logs
        isQuitting = true;
      }
    });
  } catch (e) {
    // Ignore EPIPE errors during quit
  }
}

// Wait for Vite dev server to be ready
async function waitForVite(maxAttempts: number = 30): Promise<boolean> {
  const http = await import('http');
  for (let i = 0; i < maxAttempts; i++) {
    try {
      await new Promise((resolve, reject) => {
        const req = http.get('http://localhost:5173', (res) => {
          resolve(res);
        });
        req.on('error', reject);
        req.setTimeout(1000, () => {
          req.destroy();
          reject(new Error('timeout'));
        });
      });
      return true;
    } catch {
      await new Promise(r => setTimeout(r, 500));
    }
  }
  return false;
}

// Create the browser window
async function createWindow(): Promise<BrowserWindow> {
  const mainWindow = new BrowserWindow({
    width: 1400,
    height: 900,
    minWidth: 900,
    minHeight: 600,
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      contextIsolation: true,
      nodeIntegration: false,
    },
    titleBarStyle: 'hidden',
    trafficLightPosition: { x: 12, y: 12 },
    show: false, // Don't show until loaded
  });

  // Load the app
  // Check if we're in development (Vite dev server should be running)
  const isDev = process.env.NODE_ENV === 'development' || !fs.existsSync(path.join(__dirname, '..', 'apps', 'web', 'dist', 'index.html'));

  if (isDev) {
    // Wait for Vite dev server to be ready
    safeLog('[Main]', 'Waiting for Vite dev server...');
    const viteReady = await waitForVite();
    if (!viteReady) {
      safeLog('[Main]', 'Vite dev server not available, loading anyway...');
    }
    mainWindow.loadURL('http://localhost:5173');
    mainWindow.webContents.openDevTools();
  } else {
    // Load production build
    mainWindow.loadFile(path.join(__dirname, '..', 'apps', 'web', 'dist', 'index.html'));
  }

  mainWindow.once('ready-to-show', () => {
    mainWindow.show();
  });

  return mainWindow;
}

// Start the backend server
function startBackend(): void {
  safeLog('[Main]', 'Starting backend server...');

  backendProcess = spawn('npx', ['tsx', 'apps/server/src/index.ts'], {
    cwd: path.join(__dirname, '..', '..'),
    stdio: 'pipe',
  });

  backendProcess.stdout?.on('data', (data: Buffer) => {
    safeLog('[Backend]', data.toString().trim());
  });

  backendProcess.stderr?.on('data', (data: Buffer) => {
    safeLog('[Backend Error]', data.toString().trim());
  });

  backendProcess.on('close', (code: number | null) => {
    safeLog('[Backend]', `Process exited with code ${code}`);
  });

  backendProcess.on('error', (err: Error) => {
    safeLog('[Backend]', `Failed to start: ${err.message}`);
  });
}

// Stop the backend server
function stopBackend(): void {
  if (backendProcess) {
    safeLog('[Main]', 'Stopping backend server...');
    backendProcess.kill();
    backendProcess = null;
  }
}

// App event handlers
app.whenReady().then(async () => {
  // Start backend server
  startBackend();

  // Create window after a short delay to let backend start
  setTimeout(async () => {
    await createWindow();
  }, 2000);

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) {
      createWindow();
    }
  });
});

app.on('window-all-closed', () => {
  isQuitting = true;
  stopBackend();
  if (process.platform !== 'darwin') {
    app.quit();
  }
});

app.on('before-quit', () => {
  isQuitting = true;
  stopBackend();
});

app.on('will-quit', () => {
  isQuitting = true;
  stopBackend();
});

// Handle EPIPE errors globally
process.on('uncaughtException', (error: Error) => {
  if (error.message?.includes('EPIPE')) {
    // Ignore EPIPE errors - they happen when stdout is closed
    isQuitting = true;
    return;
  }
  // Re-throw other errors
  throw error;
});

import { pgTable, uuid, varchar, text, boolean, timestamp, integer, jsonb, inet, date, index, unique } from 'drizzle-orm/pg-core';
import { relations } from 'drizzle-orm';

// ============================================
// USERS
// ============================================
export const users = pgTable('users', {
  id: uuid('id').primaryKey().defaultRandom(),
  email: varchar('email', { length: 255 }).notNull().unique(),
  passwordHash: varchar('password_hash', { length: 255 }).notNull(),
  displayName: varchar('display_name', { length: 100 }),
  isActive: boolean('is_active').default(true),
  createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  lastLoginAt: timestamp('last_login_at', { withTimezone: true })
}, (table) => [
  index('idx_users_email').on(table.email)
]);

// ============================================
// SESSIONS (HTTP-only cookie based)
// ============================================
export const sessions = pgTable('sessions', {
  id: varchar('id', { length: 64 }).primaryKey(),
  userId: uuid('user_id').notNull().references(() => users.id, { onDelete: 'cascade' }),
  userAgent: text('user_agent'),
  ipAddress: varchar('ip_address', { length: 45 }),
  expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
  createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull()
}, (table) => [
  index('idx_sessions_user').on(table.userId),
  index('idx_sessions_expires').on(table.expiresAt)
]);

