/**
 * useChatActions - Chat CRUD actions
 * 
 * Handles creating, loading, and deleting chats.
 */
import { useState, useCallback, useEffect } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import type { Chat } from '@normie/types';
import { transformApiChat } from '@normie/utils';
import { chatApi } from '@/lib/api';
import { chatKeys } from './useChats';
import { setCurrentChatId, getCurrentChatId } from '@/lib/storage';

interface UseChatActionsParams {
  workspaceId: string | undefined;
  isLoggedIn: boolean;
  chats: Chat[];
  isStreaming: boolean;
  abortStreaming: () => void;
  clearAuthState: () => void;
  onChatLoaded: (chat: Chat) => void;
  reset: () => void;
}

interface UseChatActionsReturn {
  currentChat: Chat | null;
  isLoading: boolean;
  createNewChat: () => void;
  loadChat: (chatId: string) => Promise<void>;
  deleteChat: (chatId: string) => Promise<void>;
  setCurrentChat: (chat: Chat | null) => void;
}

export function useChatActions(params: UseChatActionsParams): UseChatActionsReturn {
  const {
    workspaceId,
    isLoggedIn,
    chats,
    isStreaming,
    abortStreaming,
    clearAuthState,
    onChatLoaded,
    reset,
  } = params;

  const queryClient = useQueryClient();
  const [currentChat, setCurrentChat] = useState<Chat | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  // Workspace change - clear current chat
  useEffect(() => {
    if (workspaceId) {
      setCurrentChat(null);
      reset();
      setCurrentChatId(null);
    }
  }, [workspaceId, reset]);

  // Restore last open chat on mount
  useEffect(() => {
    const restoreLastChat = async () => {
      if (isLoggedIn && workspaceId && chats.length > 0) {
        const lastChatId = getCurrentChatId();
        if (lastChatId && chats.some((c) => c.id === lastChatId)) {
          await loadChat(lastChatId);
        }
      }
    };
    restoreLastChat();
  }, [isLoggedIn, workspaceId, chats.length]); // eslint-disable-line react-hooks/exhaustive-deps

  const createNewChat = useCallback(() => {
    if (isStreaming) {
      abortStreaming();
    }
    setCurrentChat(null);
    reset();
    setCurrentChatId(null);
  }, [isStreaming, abortStreaming, reset]);

  const loadChat = useCallback(
    async (chatId: string) => {
      if (isStreaming) {
        abortStreaming();
      }

      // First, check if we have a cached version with messages
      const cachedChat = chats.find((c) => c.id === chatId);
      if (cachedChat && cachedChat.messages.length > 0) {
        setCurrentChat(cachedChat);
        onChatLoaded(cachedChat);
        setCurrentChatId(chatId);
        return;
      }

      // If not cached or empty, load from API
      if (!isLoggedIn || !workspaceId) {
        return;
      }

      setIsLoading(true);
      try {
        const chatData = await chatApi.get(chatId);
        const chat = transformApiChat(chatData);
        setCurrentChat(chat);
        onChatLoaded(chat);
        setCurrentChatId(chatId);

        // Update the chats list cache with this chat's metadata
        queryClient.setQueryData(chatKeys.list(workspaceId), (old: Chat[] | undefined) => {
          if (!old) return old;
          const exists = old.find((c) => c.id === chatId);
          if (exists) {
            return old.map((c) => (c.id === chatId ? { ...c, messages: [] } : c));
          }
          return [{ ...chat, messages: [] }, ...old];
        });
      } catch (err) {
        console.error('[useChatActions] Failed to load chat:', err);
        if (err instanceof Error && err.message.includes('Session expired')) {
          clearAuthState();
          queryClient.clear();
        }
      } finally {
        setIsLoading(false);
      }
    },
    [chats, isLoggedIn, workspaceId, isStreaming, abortStreaming, clearAuthState, queryClient, onChatLoaded],
  );

  const deleteChat = useCallback(
    async (chatId: string) => {
      try {
        if (isLoggedIn) {
          await chatApi.delete(chatId);
        }
        queryClient.invalidateQueries({ queryKey: ['chats', 'list'] });
        queryClient.removeQueries({ queryKey: chatKeys.detail(chatId) });

        if (currentChat?.id === chatId) {
          createNewChat();
        }
      } catch (err) {
        console.error('[useChatActions] Failed to delete chat:', err);
        if (err instanceof Error && err.message.includes('Session expired')) {
          clearAuthState();
          queryClient.clear();
        }
      }
    },
    [currentChat, isLoggedIn, createNewChat, clearAuthState, queryClient],
  );

  return {
    currentChat,
    isLoading,
    createNewChat,
    loadChat,
    deleteChat,
    setCurrentChat,
  };
}

/**
 * useChatSender - Send message orchestration
 * 
 * Extracted from ChatContext to keep context stateless.
 * Handles the logic of sending a message and updating state.
 */
import { useCallback } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import type { Chat, Message, Provider, Todo, ToolCall } from '@normie/types';
import { chatKeys } from './useChats';

interface UseChatSenderParams {
  currentChat: Chat | null;
  workspaceId: string | undefined;
  provider: Provider;
  model: string;
  userId: string | undefined;
  messages: Message[];
  todos: Todo[];
  toolCalls: ToolCall[];
  isStreaming: boolean;
  sendStreamMessage: (params: {
    content: string;
    chatId: string;
    chatTitle: string;
    provider: Provider;
    model: string;
    workspaceId: string | null;
    userId: string;
  }) => Promise<{ chatId: string; chatTitle: string } | null>;
  setCurrentChat: (chat: Chat | null) => void;
}

interface UseChatSenderReturn {
  sendMessage: (content: string) => Promise<void>;
}

export function useChatSender(params: UseChatSenderParams): UseChatSenderReturn {
  const {
    currentChat,
    workspaceId,
    provider,
    model,
    userId,
    messages,
    todos,
    toolCalls,
    isStreaming,
    sendStreamMessage,
    setCurrentChat,
  } = params;

  const queryClient = useQueryClient();

  const sendMessage = useCallback(
    async (content: string) => {
      if (!content.trim() || isStreaming || !userId) return;

      const chatId = currentChat?.id || crypto.randomUUID();
      const chatTitle =
        currentChat?.title ||
        (content.length > 30 ? content.substring(0, 30) + '...' : content);

      const result = await sendStreamMessage({
        content,
        chatId,
        chatTitle,
        provider,
        model,
        workspaceId: workspaceId || null,
        userId,
      });

      if (result) {
        // Filter out error messages for final state
        const finalMessages: Message[] = messages.filter((m) =>
          !m.content.startsWith('[Error:')
        );

        const updatedChat: Chat = {
          id: result.chatId,
          title: result.chatTitle,
          provider,
          model,
          updatedAt: Date.now(),
          messages: finalMessages,
          todos,
          toolCalls,
        };

        setCurrentChat(updatedChat);

        // Refresh chat list from server
        queryClient.invalidateQueries({ queryKey: ['chats', 'list'] });
      }
    },
    [
      currentChat,
      workspaceId,
      provider,
      model,
      userId,
      messages,
      todos,
      toolCalls,
      isStreaming,
      sendStreamMessage,
      setCurrentChat,
      queryClient,
    ],
  );

  return { sendMessage };
}

/**
 * useChatStream - Simple streaming without over-engineering
 *
 * REALITY CHECK:
 * ChatGPT, Claude.ai, etc. achieve smooth streaming because:
 * 1. Their backends send small, frequent chunks (1-10 chars at a time)
 * 2. They use simple React rendering - no fancy tricks
 * 3. The "smoothness" is from consistent chunk timing, not frontend magic
 *
 * If your backend sends big chunks infrequently, NO frontend trick will help.
 */
import { useState, useRef, useCallback } from 'react';
import type { Message, ToolCall, Todo, InlineToolCall, Provider } from '@normie/types';
import { generateId } from '@normie/utils';
import { chatApi } from '@/lib/api';

// Helper to check if error is a user-initiated abort
function isAbortError(error: unknown): boolean {
  if (error instanceof Error) {
    return error.name === 'AbortError' ||
           error.message?.includes('abort') ||
           error.message?.includes('cancelled') ||
           error.message?.includes('The operation was aborted');
  }
  return false;
}

interface UseChatStreamReturn {
  messages: Message[];
  isStreaming: boolean;
  toolCalls: ToolCall[];
  todos: Todo[];
  sendMessage: (params: {
    content: string;
    chatId: string;
    chatTitle: string;
    provider: Provider;
    model: string;
    workspaceId: string | null;
    userId: string;
  }) => Promise<{ chatId: string; chatTitle: string } | null>;
  stopStreaming: (chatId: string, provider: Provider) => Promise<void>;
  setMessages: React.Dispatch<React.SetStateAction<Message[]>>;
  setToolCalls: React.Dispatch<React.SetStateAction<ToolCall[]>>;
  setTodos: React.Dispatch<React.SetStateAction<Todo[]>>;
  loadMessages: (chat: { messages: Message[]; todos?: Todo[]; toolCalls?: ToolCall[] }) => void;
  reset: () => void;
}

export function useChatStream(): UseChatStreamReturn {
  const [messages, setMessages] = useState<Message[]>([]);
  const [isStreaming, setIsStreaming] = useState(false);
  const [toolCalls, setToolCalls] = useState<ToolCall[]>([]);
  const [todos, setTodos] = useState<Todo[]>([]);

  const abortControllerRef = useRef<AbortController | null>(null);

  const reset = useCallback(() => {
    setMessages([]);
    setToolCalls([]);
    setTodos([]);
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
  }, []);

  const loadMessages = useCallback((chat: { messages: Message[]; todos?: Todo[]; toolCalls?: ToolCall[] }) => {
    setMessages(chat.messages);
    setTodos(chat.todos || []);
    setToolCalls(chat.toolCalls || []);
  }, []);

  const stopStreaming = useCallback(async (chatId: string, provider: Provider) => {
    window.electronAPI?.abortCurrentRequest();
    if (chatId) {
      await chatApi.abort(chatId, provider);
    }
    setIsStreaming(false);
  }, []);

  const sendMessage = useCallback(
    async (params: {
      content: string;
      chatId: string;
      chatTitle: string;
      provider: Provider;
      model: string;
      workspaceId: string | null;
      userId: string;
    }): Promise<{ chatId: string; chatTitle: string } | null> => {
      const { content, chatId, chatTitle, provider, model, workspaceId, userId } = params;

      if (!content.trim() || isStreaming) return null;

      const userMessage: Message = {
        id: generateId(),
        role: 'user',
        content: content.trim(),
      };

      // Add user message
      setMessages((prev) => [...prev, userMessage]);

      // Create placeholder assistant message
      const assistantMessageId = generateId();
      setMessages((prev) => [
        ...prev,
        {
          id: assistantMessageId,
          role: 'assistant',
          content: '',
          reasoning: '',
          inlineToolCalls: [],
        },
      ]);

      setIsStreaming(true);

      try {
        const reader = await chatApi.send({
          content,
          chatId,
          provider,
          model,
          workspaceId,
          userId,
        });

        let fullContent = '';
        let fullReasoning = '';
        const pendingToolCalls = new Map<string, string>();

        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          if (!value) continue;

          // Parse SSE data
          const lines = value.split('\n');
          for (const line of lines) {
            if (line.startsWith(':')) continue;
            if (!line.startsWith('data: ')) continue;

            try {
              const data = JSON.parse(line.slice(6));

              switch (data.type) {
                case 'text':
                  if (data.content) {
                    if (data.isReasoning) {
                      fullReasoning += data.content;
                    } else {
                      fullContent += data.content;
                    }
                    // Simple React update - this is how most apps do it
                    setMessages((prev) =>
                      prev.map((m) =>
                        m.id === assistantMessageId
                          ? { ...m, content: fullContent, reasoning: fullReasoning }
                          : m
                      )
                    );
                  }
                  break;

                case 'tool_use':
                  if (data.name) {
                    const localToolId = generateId();

                    const toolCall: ToolCall = {
                      id: localToolId,
                      name: data.name,
                      input: data.input || {},
                      status: 'running',
                    };
                    setToolCalls((prev) => [...prev, toolCall]);

                    if (data.id) {
                      pendingToolCalls.set(data.id, localToolId);
                    }

                    const inlineToolCall: InlineToolCall = {
                      id: localToolId,
                      name: data.name,
                      input: data.input || {},
                      status: 'running',
                    };
                    setMessages((prev) =>
                      prev.map((m) =>
                        m.id === assistantMessageId
                          ? {
                              ...m,
                              inlineToolCalls: [
                                ...(m.inlineToolCalls || []),
                                inlineToolCall,
                              ],
                            }
                          : m
                      )
                    );

                    if (data.name === 'TodoWrite' && data.input?.todos) {
                      setTodos(data.input.todos as Todo[]);
                    }
                  }
                  break;

                case 'tool_result':
                  if (data.tool_use_id || data.result !== undefined) {
                    const apiToolId = data.tool_use_id;
                    const localId = apiToolId
                      ? pendingToolCalls.get(apiToolId)
                      : null;

                    if (localId) {
                      setToolCalls((prev) =>
                        prev.map((t) =>
                          t.id === localId
                            ? { ...t, status: 'success', result: data.result }
                            : t
                        )
                      );

                      setMessages((prev) =>
                        prev.map((m) =>
                          m.id === assistantMessageId
                            ? {
                                ...m,
                                inlineToolCalls:
                                  m.inlineToolCalls?.map((t) =>
                                    t.id === localId
                                      ? {
                                          ...t,
                                          status: 'success',
                                          result: data.result,
                                        }
                                      : t
                                  ) || [],
                              }
                            : m
                        )
                      );

                      pendingToolCalls.delete(apiToolId);
                    }
                  }
                  break;

                case 'error':
                  throw new Error(data.message || 'Stream error');
              }
            } catch {
              // Skip parse errors
            }
          }
        }

        // Final update
        setMessages((prev) =>
          prev.map((m) => {
            if (m.id !== assistantMessageId) return m;
            return {
              ...m,
              content: fullContent,
              reasoning: fullReasoning || undefined,
              inlineToolCalls: m.inlineToolCalls?.length
                ? m.inlineToolCalls
                : undefined,
            };
          })
        );

        return { chatId, chatTitle };
      } catch (error) {
        console.error('[useChatStream] Error:', error);

        // Don't show error for user-initiated abort
        if (isAbortError(error)) {
          console.log('[useChatStream] Stream aborted by user, not an error');
          // Clean up: remove empty placeholder or keep accumulated content
          setMessages((prev) =>
            prev.map((m) =>
              m.id === assistantMessageId
                ? {
                    ...m,
                    // Keep accumulated content, clean up reasoning if empty
                    reasoning: m.reasoning || undefined,
                  }
                : m
            )
          );
        } else {
          // Only show error for actual errors (not aborts)
          setMessages((prev) =>
            prev.map((m) =>
              m.id === assistantMessageId
                ? {
                    ...m,
                    content:
                      m.content +
                      `\n\n[Error: ${error instanceof Error ? error.message : 'Unknown error'}]`,
                  }
                : m
            )
          );
        }

        return null;
      } finally {
        setIsStreaming(false);
      }
    },
    [isStreaming]
  );

  return {
    messages,
    isStreaming,
    toolCalls,
    todos,
    sendMessage,
    stopStreaming,
    setMessages,
    setToolCalls,
    setTodos,
    loadMessages,
    reset,
  };
}

/**
 * Base provider interface for AI agent providers.
 * All providers must implement these methods.
 */

import type { StreamChunk } from '@normie/types';

/**
 * Parameters for provider query method
 */
export interface QueryParams {
  /** The current user message */
  prompt: string;
  /** Conversation history with current message */
  messages: Array<{ role: string; content: string }>;
  /** System prompt from workspace context */
  systemPrompt?: string;
  /** Chat session identifier */
  chatId: string;
  /** Existing session ID from DB (for resumption) */
  sessionId?: string;
  /** User identifier */
  userId: string;
  /** MCP server configurations */
  mcpServers?: Record<string, unknown>;
  /** List of allowed tool names */
  allowedTools?: string[];
  /** Maximum conversation turns */
  maxTurns?: number;
  /** Model to use */
  model?: string;
}

/**
 * Provider configuration object
 */
export interface ProviderConfig {
  [key: string]: unknown;
}

/**
 * Message format for conversation history
 */
export interface HistoryMessage {
  role: 'user' | 'assistant';
  content: string;
}

/**
 * Base provider abstract class for AI agent providers.
 * All providers must extend this class and implement the abstract methods.
 */
export abstract class BaseProvider {
  protected config: ProviderConfig;
  protected sessions: Map<string, string>;

  constructor(config: ProviderConfig = {}) {
    this.config = config;
    this.sessions = new Map();
  }

  /**
   * Get the provider name
   */
  abstract get name(): string;

  /**
   * Initialize the provider
   */
  abstract initialize(): Promise<void>;

  /**
   * Execute a query/prompt and yield streaming responses
   * @param params - Query parameters
   * @yields Streaming response chunks
   */
  abstract query(params: QueryParams): AsyncGenerator<StreamChunk>;

  /**
   * Build a prompt string from messages array (for providers that don't support native history)
   * @param messages - Conversation history
   * @param systemPrompt - Optional system prompt
   * @returns Formatted prompt string
   */
  protected buildPromptFromHistory(
    messages: HistoryMessage[],
    systemPrompt?: string | null
  ): string {
    const parts: string[] = [];

    if (systemPrompt) {
      parts.push(systemPrompt);
      parts.push('---');
    }

    for (const msg of messages) {
      if (msg.role === 'user') {
        parts.push(`User: ${msg.content}`);
      } else if (msg.role === 'assistant') {
        parts.push(`Assistant: ${msg.content}`);
      }
    }

    return parts.join('\n\n');
  }

  /**
   * Get or create a session for a chat
   * @param chatId - Chat identifier
   * @returns Session ID if exists, null otherwise
   */
  getSession(chatId: string): string | null {
    return this.sessions.get(chatId) || null;
  }

  /**
   * Store a session ID for a chat
   * @param chatId - Chat identifier
   * @param sessionId - Session identifier to store
   */
  setSession(chatId: string, sessionId: string): void {
    this.sessions.set(chatId, sessionId);
  }

  /**
   * Abort an active query for a given chatId
   * @param chatId - Chat identifier
   * @returns True if aborted, false if no active query
   */
  abort(_chatId: string): boolean {
    // Override in subclass to implement abort functionality
    return false;
  }

  /**
   * Cleanup resources
   */
  async cleanup(): Promise<void> {
    this.sessions.clear();
  }
}

