/**
 * useChatActions - Chat CRUD actions
 * 
 * Handles creating, loading, and deleting chats.
 */
import { useState, useCallback, useEffect } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import type { Chat } from '@normie/types';
import { transformApiChat } from '@normie/utils';
import { chatApi } from '@/lib/api';
import { chatKeys } from './useChats';
import { setCurrentChatId, getCurrentChatId } from '@/lib/storage';

interface UseChatActionsParams {
  workspaceId: string | undefined;
  isLoggedIn: boolean;
  chats: Chat[];
  isStreaming: boolean;
  abortStreaming: () => void;
  clearAuthState: () => void;
  onChatLoaded: (chat: Chat) => void;
  reset: () => void;
}

interface UseChatActionsReturn {
  currentChat: Chat | null;
  isLoading: boolean;
  createNewChat: () => void;
  loadChat: (chatId: string) => Promise<void>;
  deleteChat: (chatId: string) => Promise<void>;
  setCurrentChat: (chat: Chat | null) => void;
}

export function useChatActions(params: UseChatActionsParams): UseChatActionsReturn {
  const {
    workspaceId,
    isLoggedIn,
    chats,
    isStreaming,
    abortStreaming,
    clearAuthState,
    onChatLoaded,
    reset,
  } = params;

  const queryClient = useQueryClient();
  const [currentChat, setCurrentChat] = useState<Chat | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  // Workspace change - clear current chat
  useEffect(() => {
    if (workspaceId) {
      setCurrentChat(null);
      reset();
      setCurrentChatId(null);
    }
  }, [workspaceId, reset]);

  // Restore last open chat on mount
  useEffect(() => {
    const restoreLastChat = async () => {
      if (isLoggedIn && workspaceId && chats.length > 0) {
        const lastChatId = getCurrentChatId();
        if (lastChatId && chats.some((c) => c.id === lastChatId)) {
          await loadChat(lastChatId);
        }
      }
    };
    restoreLastChat();
  }, [isLoggedIn, workspaceId, chats.length]); // eslint-disable-line react-hooks/exhaustive-deps

  const createNewChat = useCallback(() => {
    if (isStreaming) {
      abortStreaming();
    }
    setCurrentChat(null);
    reset();
    setCurrentChatId(null);
  }, [isStreaming, abortStreaming, reset]);

  const loadChat = useCallback(
    async (chatId: string) => {
      if (isStreaming) {
        abortStreaming();
      }

      // First, check if we have a cached version with messages
      const cachedChat = chats.find((c) => c.id === chatId);
      if (cachedChat && cachedChat.messages.length > 0) {
        setCurrentChat(cachedChat);
        onChatLoaded(cachedChat);
        setCurrentChatId(chatId);
        return;
      }

      // If not cached or empty, load from API
      if (!isLoggedIn || !workspaceId) {
        return;
      }

      setIsLoading(true);
      try {
        const chatData = await chatApi.get(chatId);
        const chat = transformApiChat(chatData);
        setCurrentChat(chat);
        onChatLoaded(chat);
        setCurrentChatId(chatId);

        // Update the chats list cache with this chat's metadata
        queryClient.setQueryData(chatKeys.list(workspaceId), (old: Chat[] | undefined) => {
          if (!old) return old;
          const exists = old.find((c) => c.id === chatId);
          if (exists) {
            return old.map((c) => (c.id === chatId ? { ...c, messages: [] } : c));
          }
          return [{ ...chat, messages: [] }, ...old];
        });
      } catch (err) {
        console.error('[useChatActions] Failed to load chat:', err);
        if (err instanceof Error && err.message.includes('Session expired')) {
          clearAuthState();
          queryClient.clear();
        }
      } finally {
        setIsLoading(false);
      }
    },
    [chats, isLoggedIn, workspaceId, isStreaming, abortStreaming, clearAuthState, queryClient, onChatLoaded],
  );

  const deleteChat = useCallback(
    async (chatId: string) => {
      try {
        if (isLoggedIn) {
          await chatApi.delete(chatId);
        }
        queryClient.invalidateQueries({ queryKey: ['chats', 'list'] });
        queryClient.removeQueries({ queryKey: chatKeys.detail(chatId) });

        if (currentChat?.id === chatId) {
          createNewChat();
        }
      } catch (err) {
        console.error('[useChatActions] Failed to delete chat:', err);
        if (err instanceof Error && err.message.includes('Session expired')) {
          clearAuthState();
          queryClient.clear();
        }
      }
    },
    [currentChat, isLoggedIn, createNewChat, clearAuthState, queryClient],
  );

  return {
    currentChat,
    isLoading,
    createNewChat,
    loadChat,
    deleteChat,
    setCurrentChat,
  };
}

/**
 * Chat hooks - queries and mutations
 * 
 * All chat operations grouped in one file.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import type { Chat } from '@normie/types';
import { transformApiChatLite } from '@normie/utils';
import { chatApi } from '@/lib/api';

// ============================================
// Query Keys
// ============================================

export const chatKeys = {
  all: ['chats'] as const,
  list: (workspaceId: string) => [...chatKeys.all, 'list', workspaceId] as const,
  detail: (chatId: string) => [...chatKeys.all, 'detail', chatId] as const,
};

// ============================================
// Queries
// ============================================

/**
 * Fetch chats for a workspace
 * 
 * @example
 * const { data: chats, isLoading } = useChats(workspaceId);
 */
export function useChats(workspaceId: string | null | undefined) {
  return useQuery({
    queryKey: chatKeys.list(workspaceId!),
    queryFn: async (): Promise<Chat[]> => {
      if (!workspaceId) return [];

      const chatsData = await chatApi.list(workspaceId);

      // Transform and sort by updated time (most recent first)
      return chatsData
        .map(transformApiChatLite)
        .sort((a, b) => b.updatedAt - a.updatedAt);
    },
    enabled: !!workspaceId,
  });
}

/**
 * Fetch a single chat with messages
 * Note: This is named useChatDetail to avoid collision with useChat() from ChatContext
 * 
 * @example
 * const { data: chat } = useChatDetail(chatId);
 */
export function useChatDetail(chatId: string | null | undefined) {
  return useQuery({
    queryKey: chatKeys.detail(chatId!),
    queryFn: async (): Promise<Chat | null> => {
      if (!chatId) return null;

      const chatData = await chatApi.get(chatId);
      return transformApiChatLite(chatData);
    },
    enabled: !!chatId,
  });
}

// ============================================
// Mutations
// ============================================

/**
 * Delete a chat
 * 
 * @example
 * const { mutate: deleteChat } = useDeleteChat();
 * deleteChat(chatId);
 */
export function useDeleteChat() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (chatId: string) => {
      await chatApi.delete(chatId);
      return chatId;
    },
    onSuccess: (chatId) => {
      // Invalidate chat lists and remove from cache
      queryClient.invalidateQueries({ queryKey: ['chats', 'list'] });
      queryClient.removeQueries({ queryKey: chatKeys.detail(chatId) });
    },
  });
}

/**
 * useChatStream - Simple streaming without over-engineering
 *
 * REALITY CHECK:
 * ChatGPT, Claude.ai, etc. achieve smooth streaming because:
 * 1. Their backends send small, frequent chunks (1-10 chars at a time)
 * 2. They use simple React rendering - no fancy tricks
 * 3. The "smoothness" is from consistent chunk timing, not frontend magic
 *
 * If your backend sends big chunks infrequently, NO frontend trick will help.
 */
import { useState, useRef, useCallback } from 'react';
import type { Message, ToolCall, Todo, InlineToolCall, Provider } from '@normie/types';
import { generateId } from '@normie/utils';
import { chatApi } from '@/lib/api';
import { queryClient } from '@/lib/query-client';

// Helper to check if error is a user-initiated abort
function isAbortError(error: unknown): boolean {
  if (error instanceof Error) {
    return error.name === 'AbortError' ||
           error.message?.includes('abort') ||
           error.message?.includes('cancelled') ||
           error.message?.includes('The operation was aborted');
  }
  return false;
}

interface UseChatStreamReturn {
  messages: Message[];
  isStreaming: boolean;
  toolCalls: ToolCall[];
  todos: Todo[];
  generatedTitle: string | null;
  sendMessage: (params: {
    content: string;
    chatId: string;
    chatTitle: string;
    provider: Provider;
    model: string;
    workspaceId: string | null;
    userId: string;
  }, callbacks?: {
    onTitleUpdate?: (title: string) => void;
  }) => Promise<{ chatId: string; chatTitle: string } | null>;
  stopStreaming: (chatId: string, provider: Provider) => Promise<void>;
  setMessages: React.Dispatch<React.SetStateAction<Message[]>>;
  setToolCalls: React.Dispatch<React.SetStateAction<ToolCall[]>>;
  setTodos: React.Dispatch<React.SetStateAction<Todo[]>>;
  loadMessages: (chat: { messages: Message[]; todos?: Todo[]; toolCalls?: ToolCall[] }) => void;
  reset: () => void;
}

export function useChatStream(): UseChatStreamReturn {
  const [messages, setMessages] = useState<Message[]>([]);
  const [isStreaming, setIsStreaming] = useState(false);
  const [toolCalls, setToolCalls] = useState<ToolCall[]>([]);
  const [todos, setTodos] = useState<Todo[]>([]);
  const [generatedTitle, setGeneratedTitle] = useState<string | null>(null);

  const abortControllerRef = useRef<AbortController | null>(null);

  const reset = useCallback(() => {
    setMessages([]);
    setToolCalls([]);
    setTodos([]);
    setGeneratedTitle(null);
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
  }, []);

  const loadMessages = useCallback((chat: { messages: Message[]; todos?: Todo[]; toolCalls?: ToolCall[] }) => {
    setMessages(chat.messages);
    setTodos(chat.todos || []);
    setToolCalls(chat.toolCalls || []);
  }, []);

  const stopStreaming = useCallback(async (chatId: string, provider: Provider) => {
    window.electronAPI?.abortCurrentRequest();
    if (chatId) {
      await chatApi.abort(chatId, provider);
    }
    setIsStreaming(false);
  }, []);

  const sendMessage = useCallback(
    async (
      params: {
        content: string;
        chatId: string;
        chatTitle: string;
        provider: Provider;
        model: string;
        workspaceId: string | null;
        userId: string;
      },
      callbacks?: {
        onTitleUpdate?: (title: string) => void;
      }
    ): Promise<{ chatId: string; chatTitle: string } | null> => {
      const { content, chatId, chatTitle, provider, model, workspaceId, userId } = params;

      if (!content.trim() || isStreaming) return null;

      const userMessage: Message = {
        id: generateId(),
        role: 'user',
        content: content.trim(),
      };

      // Add user message
      setMessages((prev) => [...prev, userMessage]);

      // Create placeholder assistant message
      const assistantMessageId = generateId();
      setMessages((prev) => [
        ...prev,
        {
          id: assistantMessageId,
          role: 'assistant',
          content: '',
          reasoning: '',
          inlineToolCalls: [],
        },
      ]);

      setIsStreaming(true);

      try {
        const reader = await chatApi.send({
          content,
          chatId,
          provider,
          model,
          workspaceId,
          userId,
        });

        let fullContent = '';
        let fullReasoning = '';
        const pendingToolCalls = new Map<string, string>();

        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          if (!value) continue;

          // Parse SSE data
          const lines = value.split('\n');
          for (const line of lines) {
            if (line.startsWith(':')) continue;
            if (!line.startsWith('data: ')) continue;

            try {
              const data = JSON.parse(line.slice(6));

              switch (data.type) {
                case 'text':
                  if (data.content) {
                    if (data.isReasoning) {
                      fullReasoning += data.content;
                    } else {
                      fullContent += data.content;
                    }
                    // Simple React update - this is how most apps do it
                    setMessages((prev) =>
                      prev.map((m) =>
                        m.id === assistantMessageId
                          ? { ...m, content: fullContent, reasoning: fullReasoning }
                          : m
                      )
                    );
                  }
                  break;

                case 'tool_use':
                  if (data.name) {
                    const localToolId = generateId();

                    const toolCall: ToolCall = {
                      id: localToolId,
                      name: data.name,
                      input: data.input || {},
                      status: 'running',
                    };
                    setToolCalls((prev) => [...prev, toolCall]);

                    if (data.id) {
                      pendingToolCalls.set(data.id, localToolId);
                    }

                    const inlineToolCall: InlineToolCall = {
                      id: localToolId,
                      name: data.name,
                      input: data.input || {},
                      status: 'running',
                    };
                    setMessages((prev) =>
                      prev.map((m) =>
                        m.id === assistantMessageId
                          ? {
                              ...m,
                              inlineToolCalls: [
                                ...(m.inlineToolCalls || []),
                                inlineToolCall,
                              ],
                            }
                          : m
                      )
                    );

                    if (data.name === 'TodoWrite' && data.input?.todos) {
                      setTodos(data.input.todos as Todo[]);
                    }
                  }
                  break;

                case 'tool_result':
                  if (data.tool_use_id || data.result !== undefined) {
                    const apiToolId = data.tool_use_id;
                    const localId = apiToolId
                      ? pendingToolCalls.get(apiToolId)
                      : null;

                    if (localId) {
                      setToolCalls((prev) =>
                        prev.map((t) =>
                          t.id === localId
                            ? { ...t, status: 'success', result: data.result }
                            : t
                        )
                      );

                      setMessages((prev) =>
                        prev.map((m) =>
                          m.id === assistantMessageId
                            ? {
                                ...m,
                                inlineToolCalls:
                                  m.inlineToolCalls?.map((t) =>
                                    t.id === localId
                                      ? {
                                          ...t,
                                          status: 'success',
                                          result: data.result,
                                        }
                                      : t
                                  ) || [],
                              }
                            : m
                        )
                      );

                      pendingToolCalls.delete(apiToolId);
                    }
                  }
                  break;

                case 'title_update':
                  // Title was auto-generated by AI after first exchange
                  if (data.title) {
                    setGeneratedTitle(data.title);
                    // Update the chat title in query cache
                    queryClient.setQueryData(['chats', 'list'], (old: unknown) => {
                      if (!old || typeof old !== 'object' || !('chats' in old)) return old;
                      const oldData = old as { chats: Array<{ id: string; title: string }> };
                      return {
                        ...oldData,
                        chats: oldData.chats.map((chat) =>
                          chat.id === chatId ? { ...chat, title: data.title } : chat
                        ),
                      };
                    });
                    // Call the callback if provided
                    callbacks?.onTitleUpdate?.(data.title);
                  }
                  break;

                case 'error':
                  throw new Error(data.message || 'Stream error');
              }
            } catch {
              // Skip parse errors
            }
          }
        }

        // Final update
        setMessages((prev) =>
          prev.map((m) => {
            if (m.id !== assistantMessageId) return m;
            return {
              ...m,
              content: fullContent,
              reasoning: fullReasoning || undefined,
              inlineToolCalls: m.inlineToolCalls?.length
                ? m.inlineToolCalls
                : undefined,
            };
          })
        );

        return { chatId, chatTitle };
      } catch (error) {
        console.error('[useChatStream] Error:', error);

        // Don't show error for user-initiated abort
        if (isAbortError(error)) {
          console.log('[useChatStream] Stream aborted by user, not an error');
          // Clean up: remove empty placeholder or keep accumulated content
          setMessages((prev) =>
            prev.map((m) =>
              m.id === assistantMessageId
                ? {
                    ...m,
                    // Keep accumulated content, clean up reasoning if empty
                    reasoning: m.reasoning || undefined,
                  }
                : m
            )
          );
        } else {
          // Only show error for actual errors (not aborts)
          setMessages((prev) =>
            prev.map((m) =>
              m.id === assistantMessageId
                ? {
                    ...m,
                    content:
                      m.content +
                      `\n\n[Error: ${error instanceof Error ? error.message : 'Unknown error'}]`,
                  }
                : m
            )
          );
        }

        return null;
      } finally {
        setIsStreaming(false);
      }
    },
    [isStreaming]
  );

  return {
    messages,
    isStreaming,
    toolCalls,
    todos,
    generatedTitle,
    sendMessage,
    stopStreaming,
    setMessages,
    setToolCalls,
    setTodos,
    loadMessages,
    reset,
  };
}

/**
 * ChatContext - Stateless orchestrator combining chat hooks
 * 
 * This context does NOT hold state. It only combines hooks and exposes
 * their values through a unified API. All logic is in hooks for testability.
 */
import { createContext, useContext, useState, useCallback } from 'react';
import type { Chat, Message, Provider, ToolCall, Todo, ThinkingMode } from '@normie/types';
import { useAuth } from './AuthContext';
import { useChats, usePreferences, useChatStream, useChatActions, useChatSender } from '@/hooks';
import { setCurrentChatId } from '@/lib/storage';

interface ChatContextType {
  // State
  chats: Chat[];
  currentChat: Chat | null;
  messages: Message[];
  isLoading: boolean;
  isStreaming: boolean;
  todos: Todo[];
  toolCalls: ToolCall[];
  selectedProvider: Provider;
  selectedModel: string;
  thinkingMode: ThinkingMode;

  // Actions
  createNewChat: () => void;
  loadChat: (chatId: string) => Promise<void>;
  deleteChat: (chatId: string) => Promise<void>;
  sendMessage: (content: string) => Promise<void>;
  stopStreaming: () => void;
  setProvider: (provider: Provider) => void;
  setModel: (model: string) => void;
  toggleThinkingMode: () => void;
  refreshChats: () => Promise<void>;
}

const ChatContext = createContext<ChatContextType | undefined>(undefined);

export function ChatProvider({ children }: { children: React.ReactNode }) {
  const { isLoggedIn, currentWorkspace, user, clearAuthState } = useAuth();

  // TanStack Query for chats list
  const { data: chats = [], refetch: refreshChats } = useChats(currentWorkspace?.id);

  // Preferences
  const {
    provider: selectedProvider,
    model: selectedModel,
    setProvider: setProviderPreference,
    setModel: setModelPreference,
  } = usePreferences();

  // Thinking mode (simple local state)
  const [thinkingMode, setThinkingMode] = useState<ThinkingMode>('normal');

  // Chat streaming
  const {
    messages,
    isStreaming,
    toolCalls,
    todos,
    sendMessage: sendStreamMessage,
    stopStreaming: stopStream,
    loadMessages,
    reset: resetStream,
  } = useChatStream();

  // Chat actions
  const {
    currentChat,
    isLoading,
    createNewChat,
    loadChat,
    deleteChat,
    setCurrentChat,
  } = useChatActions({
    workspaceId: currentWorkspace?.id,
    isLoggedIn,
    chats,
    isStreaming,
    abortStreaming: () => stopStream(currentChat?.id || '', selectedProvider),
    clearAuthState,
    onChatLoaded: (chat) => loadMessages(chat),
    reset: resetStream,
  });

  // Chat sender (extracted orchestration logic)
  const { sendMessage } = useChatSender({
    currentChat,
    workspaceId: currentWorkspace?.id,
    provider: selectedProvider,
    model: selectedModel,
    userId: user?.id,
    messages,
    todos,
    toolCalls,
    isStreaming,
    sendStreamMessage,
    setCurrentChat,
  });

  // Stop streaming wrapper
  const stopStreaming = useCallback(async () => {
    if (!isStreaming || !currentChat) return;
    await stopStream(currentChat.id, selectedProvider);
  }, [isStreaming, currentChat, selectedProvider, stopStream]);

  // Provider/model setters
  const setProvider = useCallback((provider: Provider) => {
    setProviderPreference(provider);
  }, [setProviderPreference]);

  const setModel = useCallback((model: string) => {
    setModelPreference(model);
  }, [setModelPreference]);

  const toggleThinkingMode = useCallback(() => {
    setThinkingMode((prev) => (prev === 'normal' ? 'extended' : 'normal'));
  }, []);

  const value: ChatContextType = {
    chats,
    currentChat,
    messages,
    isLoading,
    isStreaming,
    todos,
    toolCalls,
    selectedProvider,
    selectedModel,
    thinkingMode,
    createNewChat,
    loadChat,
    deleteChat,
    sendMessage,
    stopStreaming,
    setProvider,
    setModel,
    toggleThinkingMode,
    refreshChats: async () => {
      await refreshChats();
    },
  };

  return <ChatContext.Provider value={value}>{children}</ChatContext.Provider>;
}

export function useChat() {
  const context = useContext(ChatContext);
  if (context === undefined) {
    throw new Error('useChat must be used within a ChatProvider');
  }
  return context;
}

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useChat } from "@/contexts/ChatContext";
import {
  ChatSidebarContainer,
  ChatInputContainer,
  MessageList,
} from "@/components/chat";
import { RightSidebar } from "@/components/RightSidebar";
import { AuthPage } from "@/pages/AuthPage";
import { ChevronLeft, PanelRightOpen } from "lucide-react";

function App() {
  const { isLoggedIn, isLoading: authLoading } = useAuth();
  const { currentChat, messages, isStreaming } = useChat();
  const [isRightSidebarOpen, setIsRightSidebarOpen] = useState(true);

  // Show auth page if not logged in
  if (!isLoggedIn && !authLoading) {
    return <AuthPage />;
  }

  // Show loading state
  if (authLoading) {
    return (
      <div className="fixed inset-0 bg-bg-base flex flex-col items-center justify-center gap-4">
        <div className="w-10 h-10 border-[3px] border-purple-400/30 border-t-purple-500 rounded-full animate-spin" />
        <p className="text-text-secondary">Loading...</p>
      </div>
    );
  }

  const isHomeView = !currentChat && messages.length === 0;

  return (
    <div className="relative h-screen flex overflow-hidden bg-zinc-50">
      {/* Left Sidebar - Chat History */}
      <ChatSidebarContainer />

      {/* Main Content */}
      <div className="flex-1 flex flex-col overflow-hidden min-w-0">
        {isHomeView ? (
          /* Home View */
          <div className="relative flex-1 flex flex-col items-center justify-center px-6 py-10 overflow-hidden bg-white">
            {/* Draggable header area for macOS - spans full width since it's inside the flex-1 container which starts after sidebar */}
            <div className="absolute top-0 left-0 right-0 h-12 app-drag-region mac-traffic-light-padding z-10" />
            <div className="mb-8">
              <div className="flex flex-col items-center gap-2">
                <h1 className="font-accent text-4xl font-normal text-text-primary tracking-tighter">
                  Mari berbincang dan berkreasi bersama 🤙
                </h1>
                <p className="text-sm text-text-tertiary mt-1 tracking-wide font-light">
                  Powered by Claude Code and Composio
                </p>
              </div>
            </div>

            <ChatInputContainer variant="home" />
          </div>
        ) : (
          /* Chat View */
          <div className="flex-1 flex h-screen overflow-hidden">
            <div className="flex-1 flex flex-col min-w-0 h-screen overflow-hidden bg-white">
              {/* Chat Header - Draggable on macOS */}
              <div className="flex items-center justify-between px-6 py-3.5 bg-white app-drag-region mac-traffic-light-padding">
                <h1 className="text-sm font-medium text-text-primary tracking-tight">
                  {currentChat?.title || "New chat"}
                </h1>
                <div className="flex items-center gap-2">
                  <button 
                    onClick={() => setIsRightSidebarOpen(prev => !prev)}
                    className="w-8 h-8 rounded-full bg-zinc-100 flex items-center justify-center hover:bg-zinc-200 transition-colors text-zinc-600 app-no-drag"
                    title={isRightSidebarOpen ? "Hide sidebar" : "Show sidebar"}
                  >
                    {isRightSidebarOpen ? (
                      <ChevronLeft className="w-4 h-4" strokeWidth={1.5} />
                    ) : (
                      <PanelRightOpen className="w-4 h-4" strokeWidth={1.5} />
                    )}
                  </button>
                </div>
              </div>

              {/* Messages */}
              <MessageList messages={messages} isStreaming={isStreaming} />

              {/* Input */}
              <ChatInputContainer variant="chat" />
            </div>

            {/* Right Sidebar */}
            {isRightSidebarOpen && <RightSidebar />}
          </div>
        )}
      </div>
    </div>
  );
}

export default App;

/**
 * ChatSidebar - Presentational component
 * 
 * Pure UI component with no context access. All data and actions come from props.
 */
import { useState, useRef, useEffect } from "react";
import {
  Search,
  PenSquare,
  Settings,
  MoreHorizontal,
  Trash2,
} from "lucide-react";

interface ChatSidebarProps {
  // User data
  user: { displayName?: string; email: string } | null;

  // Workspace data
  currentWorkspace: { id: string; name: string } | null;
  workspaces: { id: string; name: string }[];
  onSwitchWorkspace: (id: string) => void;
  onCreateWorkspace: (name: string, description?: string) => Promise<unknown>;

  // Chat data
  chats: { id: string; title: string }[];
  currentChatId: string | null;
  onLoadChat: (id: string) => void;
  onCreateChat: () => void;
  onDeleteChat: (id: string) => void;

  // Settings
  onOpenSettings: () => void;
}

export function ChatSidebar({
  user,
  currentWorkspace,
  workspaces,
  onSwitchWorkspace,
  onCreateWorkspace,
  chats,
  currentChatId,
  onLoadChat,
  onCreateChat,
  onDeleteChat,
  onOpenSettings,
}: ChatSidebarProps) {
  const [searchQuery, setSearchQuery] = useState("");
  const [openDropdown, setOpenDropdown] = useState<string | null>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Filter chats based on search query
  const filteredChats = chats.filter((chat) =>
    chat.title.toLowerCase().includes(searchQuery.toLowerCase()),
  );

  // Get user initials for avatar
  const getUserInitials = () => {
    if (!user) return "U";
    const name = user.displayName || user.email;
    return name.substring(0, 2).toUpperCase();
  };

  const handleDeleteChat = (e: React.MouseEvent, chatId: string) => {
    e.stopPropagation();
    if (window.confirm("Are you sure you want to delete this chat?")) {
      onDeleteChat(chatId);
      setOpenDropdown(null);
    }
  };

  const toggleDropdown = (e: React.MouseEvent, chatId: string) => {
    e.stopPropagation();
    setOpenDropdown(openDropdown === chatId ? null : chatId);
  };

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        dropdownRef.current &&
        !dropdownRef.current.contains(event.target as Node)
      ) {
        setOpenDropdown(null);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  return (
    <aside className="relative bg-white border-r border-zinc-200 p-4 pt-16 gap-3 flex-col w-[280px] flex-shrink-0 flex overflow-y-auto">
      {/* Draggable header area for macOS */}
      <div className="absolute top-0 left-0 right-0 h-12 app-drag-region z-10" />
      {/* Workspace Selector */}
      <WorkspaceSelector
        currentWorkspace={currentWorkspace}
        workspaces={workspaces}
        onSwitchWorkspace={onSwitchWorkspace}
        onCreateWorkspace={onCreateWorkspace}
      />

      {/* New Chat Button */}
      <button
        onClick={onCreateChat}
        className="flex items-center gap-1.5 bg-zinc-100 rounded-full py-1.5 px-3 hover:bg-zinc-200 transition-colors w-full justify-center"
      >
        <PenSquare className="w-3.5 h-3.5 text-zinc-600" strokeWidth={1.5} />
        <span className="text-[0.9375rem] text-zinc-600 font-light">New Chat</span>
      </button>

      {/* Search */}
      <div className="flex items-center gap-2 bg-zinc-50 border border-zinc-200 rounded-xl py-2 px-3 w-full">
        <Search className="w-3.5 h-3.5 text-zinc-400" strokeWidth={1.5} />
        <input
          type="text"
          placeholder="Search..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="bg-transparent border-none outline-none text-[0.9375rem] text-zinc-900 w-full placeholder-zinc-400 font-light"
        />
      </div>

      {/* Conversation List */}
      <div className="flex flex-col gap-0.5 flex-1 overflow-y-auto">
        {filteredChats.length === 0 ? (
          <div className="p-4 text-center text-zinc-400 text-[0.9375rem] font-light">
            {searchQuery ? "No chats found" : "No chats yet"}
          </div>
        ) : (
          filteredChats.map((chat) => (
            <div
              key={chat.id}
              className={`group relative flex items-center gap-2 rounded-xl py-2 pl-3 pr-2 transition-colors ${
                currentChatId === chat.id ? "bg-zinc-100" : "hover:bg-zinc-50"
              }`}
            >
              {/* Chat title - clickable */}
              <button
                onClick={() => onLoadChat(chat.id)}
                className="flex-1 text-left min-w-0 flex items-center gap-2"
              >
                {/* Active indicator dot */}
                {currentChatId === chat.id && (
                  <div className="w-1.5 h-1.5 rounded-full bg-green-400 flex-shrink-0"></div>
                )}
                <span
                  className={`text-[0.9375rem] tracking-tight truncate block ${
                    currentChatId === chat.id
                      ? "font-medium text-zinc-950"
                      : "font-light text-zinc-600"
                  }`}
                >
                  {chat.title}
                </span>
              </button>

              {/* Three dots dropdown button - shows on hover */}
              <div
                className="relative flex-shrink-0"
                ref={openDropdown === chat.id ? dropdownRef : null}
              >
                <button
                  onClick={(e) => toggleDropdown(e, chat.id)}
                  className="opacity-0 group-hover:opacity-100 w-6 h-6 rounded-md flex items-center justify-center hover:bg-zinc-200 transition-all text-zinc-500 hover:text-zinc-700"
                  title="Options"
                >
                  <MoreHorizontal className="w-3.5 h-3.5" strokeWidth={1.5} />
                </button>

                {/* Dropdown menu */}
                {openDropdown === chat.id && (
                  <div className="absolute right-0 top-8 w-40 bg-white border border-zinc-200 rounded-lg shadow-lg py-1 z-50">
                    <button
                      onClick={(e) => handleDeleteChat(e, chat.id)}
                      className="w-full flex items-center gap-2 px-3 py-2 text-[0.9375rem] font-light text-red-600 hover:bg-red-50 transition-colors"
                    >
                      <Trash2 className="w-3.5 h-3.5" strokeWidth={1.5} />
                      <span>Delete</span>
                    </button>
                  </div>
                )}
              </div>
            </div>
          ))
        )}
      </div>

      {/* Bottom Settings */}
      <button
        onClick={onOpenSettings}
        className="flex items-center gap-2.5 hover:bg-zinc-50 rounded-xl p-2 w-full transition-colors"
      >
        <div className="w-7 h-7 rounded-full bg-cyan-400 flex items-center justify-center flex-shrink-0">
          <span className="text-[0.9375rem] font-medium text-zinc-950">
            {getUserInitials()}
          </span>
        </div>
        <div className="flex flex-col flex-1 min-w-0 text-left">
          <span className="text-[0.9375rem] font-normal text-zinc-950 truncate">
            {user?.displayName || user?.email?.split("@")[0] || "User"}
          </span>
        </div>
        <Settings
          className="w-4 h-4 text-zinc-400 flex-shrink-0"
          strokeWidth={1.5}
        />
      </button>
    </aside>
  );
}

// ============================================
// Workspace Selector (internal presentational)
// ============================================

interface WorkspaceSelectorProps {
  currentWorkspace: { id: string; name: string } | null;
  workspaces: { id: string; name: string }[];
  onSwitchWorkspace: (id: string) => void;
  onCreateWorkspace: (name: string, description?: string) => Promise<unknown>;
}

function WorkspaceSelector({
  currentWorkspace,
  workspaces,
  onSwitchWorkspace,
  onCreateWorkspace,
}: WorkspaceSelectorProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [isCreating, setIsCreating] = useState(false);
  const [newWorkspaceName, setNewWorkspaceName] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
        setIsCreating(false);
        setNewWorkspaceName('');
        setError(null);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Focus input when creating
  useEffect(() => {
    if (isCreating && inputRef.current) {
      inputRef.current.focus();
    }
  }, [isCreating]);

  // Get workspace initials for avatar
  const getWorkspaceInitials = () => {
    if (!currentWorkspace) return 'WS';
    return currentWorkspace.name.substring(0, 2).toUpperCase();
  };

  // Get a color based on workspace name
  const getWorkspaceColor = () => {
    if (!currentWorkspace) return 'bg-gray-400';
    const colors = [
      'bg-green-400',
      'bg-blue-400',
      'bg-purple-400',
      'bg-pink-400',
      'bg-orange-400',
      'bg-cyan-400',
    ];
    const index = currentWorkspace.name.charCodeAt(0) % colors.length;
    return colors[index];
  };

  const handleSelectWorkspace = (workspaceId: string) => {
    if (workspaceId === currentWorkspace?.id) {
      setIsOpen(false);
      return;
    }

    onSwitchWorkspace(workspaceId);
    setIsOpen(false);
  };

  const handleStartCreate = () => {
    setIsCreating(true);
    setError(null);
  };

  const handleCancelCreate = () => {
    setIsCreating(false);
    setNewWorkspaceName('');
    setError(null);
  };

  const handleCreateWorkspace = async () => {
    const name = newWorkspaceName.trim();
    if (!name) {
      setError('Workspace name is required');
      return;
    }

    setIsSubmitting(true);
    setError(null);

    try {
      await onCreateWorkspace(name);
      setIsCreating(false);
      setIsOpen(false);
      setNewWorkspaceName('');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create workspace');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleCreateWorkspace();
    } else if (e.key === 'Escape') {
      handleCancelCreate();
    }
  };

  return (
    <div className="relative" ref={dropdownRef}>
      <button
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        className="flex items-center gap-2 hover:bg-zinc-50 rounded-xl px-2 py-1.5 -mx-2 transition-colors flex-1"
      >
        <div className={`w-7 h-7 rounded-lg ${getWorkspaceColor()} flex items-center justify-center flex-shrink-0`}>
          <span className="text-[0.9375rem] font-medium text-zinc-950">
            {getWorkspaceInitials()}
          </span>
        </div>
        <div className="flex flex-col flex-1 min-w-0 text-left">
          <span className="text-[0.9375rem] font-medium text-zinc-950 truncate tracking-tight">
            {currentWorkspace?.name || 'Select workspace'}
          </span>
        </div>
        <ChevronDown className={`w-4 h-4 text-zinc-400 flex-shrink-0 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
      </button>

      {isOpen && (
        <div className="absolute left-0 right-0 top-full mt-1 bg-white border border-zinc-200 rounded-xl shadow-lg p-1.5 z-50 min-w-[200px]">
          {isCreating ? (
            <div className="p-2">
              <input
                ref={inputRef}
                type="text"
                placeholder="Workspace name"
                value={newWorkspaceName}
                onChange={(e) => setNewWorkspaceName(e.target.value)}
                onKeyDown={handleKeyDown}
                disabled={isSubmitting}
                className="w-full text-[0.9375rem] bg-zinc-50 border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-coral/20 focus:border-coral transition-all"
                autoFocus
              />
              {error && (
                <p className="text-[0.9375rem] text-red-500 mt-1.5">{error}</p>
              )}
              <div className="flex gap-2 mt-2">
                <button
                  onClick={handleCancelCreate}
                  disabled={isSubmitting}
                  className="flex-1 text-[0.9375rem] text-zinc-600 hover:text-zinc-900 py-1.5 transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={handleCreateWorkspace}
                  disabled={isSubmitting || !newWorkspaceName.trim()}
                  className="flex-1 bg-zinc-900 text-white text-[0.9375rem] py-1.5 rounded-lg hover:bg-zinc-800 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-1"
                >
                  {isSubmitting ? (
                    <>
                      <Loader2 className="w-3 h-3 animate-spin" />
                      Creating
                    </>
                  ) : (
                    'Create'
                  )}
                </button>
              </div>
            </div>
          ) : (
            <>
              {/* Workspace list */}
              <div className="max-h-48 overflow-y-auto">
                {workspaces.map((workspace) => (
                  <button
                    key={workspace.id}
                    onClick={() => handleSelectWorkspace(workspace.id)}
                    className={`w-full flex items-center gap-2 px-2 py-2 rounded-lg transition-colors text-left ${
                      currentWorkspace?.id === workspace.id
                        ? 'bg-zinc-100'
                        : 'hover:bg-zinc-50'
                    }`}
                  >
                    <div className={`w-6 h-6 rounded-md ${currentWorkspace?.id === workspace.id ? getWorkspaceColor() : 'bg-zinc-200'} flex items-center justify-center flex-shrink-0`}>
                      <span className="text-[10px] font-medium text-zinc-950">
                        {workspace.name.substring(0, 2).toUpperCase()}
                      </span>
                    </div>
                    <span className="text-[0.9375rem] text-zinc-900 truncate flex-1">
                      {workspace.name}
                    </span>
                    {currentWorkspace?.id === workspace.id && (
                      <Check size={16} className="text-coral flex-shrink-0" />
                    )}
                  </button>
                ))}
              </div>

              {/* Create new workspace */}
              {workspaces.length > 0 && (
                <div className="border-t border-zinc-100 mt-1 pt-1">
                  <button
                    onClick={handleStartCreate}
                    className="w-full flex items-center gap-2 px-2 py-2 rounded-lg hover:bg-zinc-50 transition-colors text-left"
                  >
                    <div className="w-6 h-6 rounded-md bg-zinc-100 flex items-center justify-center flex-shrink-0">
                      <Plus size={14} className="text-zinc-500" />
                    </div>
                    <span className="text-[0.9375rem] text-zinc-600">New workspace</span>
                  </button>
                </div>
              )}
            </>
          )}
        </div>
      )}
    </div>
  );
}

