export function ChatInputContainer({ variant = "chat" }: { variant?: "home" | "chat" }) {
  const {
    sendMessage,
    stopStreaming,
    isStreaming,
    selectedProvider,
    selectedModel,
    setProvider,
    setModel,
  } = useChat();

  // Get available providers and models
  const providers: Provider[] = useMemo(() => 
    Object.keys(PROVIDER_MODELS) as Provider[],
    []
  );

