    PROVIDER_MODELS[selectedProvider] || [],
    [selectedProvider]
  );

  return (
    <ChatInput
      variant={variant}
      selectedProvider={selectedProvider}
      selectedModel={selectedModel}
      providers={providers}
      models={models}
      providerLabels={PROVIDER_LABELS}
