```tsx
/**
 * MessageList - Simple scrollable message list
 */
import type { Message } from "@normie/types";
import { MessageItem } from "./MessageItem";

interface MessageListProps {
  messages: Message[];
  isStreaming: boolean;
}

export function MessageList({ messages, isStreaming }: MessageListProps) {
  const isLastMessageStreaming =
    isStreaming &&
    messages.length > 0 &&
    messages[messages.length - 1].role === "assistant";

  return (
    <div className="flex-1 overflow-y-auto px-6 py-6">
      <div className="max-w-[720px] mx-auto space-y-4 px-4">
        {messages.map((message, index) => (
          <MessageItem
            key={message.id}
            message={message}
            isStreaming={
              isLastMessageStreaming && index === messages.length - 1
            }
          />
        ))}
      </div>
    </div>
  );
}
```

**Key changes:**
- Removed `useSmartScroll` hook (add back later if needed)
- Removed `ScrollToBottomButton` 
- Removed `relative` positioning
- Removed `bottomRef`
- Simple `flex-1 overflow-y-auto` - scrolls naturally
- Parent (App.tsx) has flex-col so this fills remaining space

